/bin/bash -lc "Rscript -e '
for (f in c(\"inputs/res_GluFevsGluFePlus.rds\",\"inputs/res_SuccvsGluFePlus.rds\")) {
 x <- readRDS(f); y <- x@listData; rn <- x@rownames; cat(\"FILE\", f, \"n\", length(rn), \"\\n\"); cat(\"cols\", paste(names(y), collapse=\",\"), \"\\n\"); cat(\"first genes\", paste(head(rn,12), collapse=\",\"), \"\\n\"); cat(\"all unique prefixes\", paste(unique(sub(\"_[0-9]+"'$","",rn)),collapse=","), "'"\\n\"); cat(\"padj NA\", sum(is.na(y"'$padj)), "log2FC NA", sum(is.na(y$log2FoldChange)), "'"\\n\"); cat(\"up sig\", sum("'!is.na(y$padj)&y$padj<0.05&y$log2FoldChange>1.5), "down sig", sum(!is.na(y$padj)&y$padj<0.05&y$log2FoldChange < -1.5), "abs sig", sum(!is.na(y$padj)&y$padj<0.05&abs(y$log2FoldChange)>1.5), "'"\\n\\n\");
}
' "

