/bin/bash -lc "Rscript -e '
cmd <- \"curl -L --fail --silent --show-error --max-time 30 https://rest.kegg.jp/link/pau/pau02010\";
ln <- readLines(pipe(cmd)); abc <- sub(\""'^pau:","", sub("'"\\\\tpau02010"'$", "", ln));
x <- readRDS("inputs/res_GluFevsGluFePlus.rds"); y<-x@listData; rn<-x@rownames; up <- rn[!is.na(y$padj)&y$padj<0.05&y$log2FoldChange>1.5]; hit <- intersect(up, abc);
cat("up",length(up),"ABC pathway genes",length(abc),"hits",length(hit),"'"\\n\"); print(hit); if(length(hit)) { z<-data.frame(gene=hit, lfc=y"'$log2FoldChange[match(hit,rn)], padj=y$padj[match(hit,rn)]); print(z[order(-z$lfc),], row.names=FALSE) }
'"' "

